package dev.livingrealms.minecraft.client;
import com.mojang.blaze3d.vertex.*;import dev.livingrealms.LivingRealms;import dev.livingrealms.minecraft.entity.BountyHunterEntity;import net.minecraft.client.model.EntityModel;import net.minecraft.client.model.geom.*;import net.minecraft.client.model.geom.builders.*;import net.minecraft.resources.ResourceLocation;import net.minecraft.util.Mth;
public final class BountyHunterModel extends EntityModel<BountyHunterEntity>{public static final ModelLayerLocation LAYER=new ModelLayerLocation(ResourceLocation.fromNamespaceAndPath(LivingRealms.MOD_ID,"bounty_hunter"),"main");private final ModelPart head,body,leftArm,rightArm,leftLeg,rightLeg;public BountyHunterModel(ModelPart root){head=root.getChild("head");body=root.getChild("body");leftArm=root.getChild("left_arm");rightArm=root.getChild("right_arm");leftLeg=root.getChild("left_leg");rightLeg=root.getChild("right_leg");}public static LayerDefinition createBodyLayer(){MeshDefinition m=new MeshDefinition();PartDefinition r=m.getRoot();r.addOrReplaceChild("head",CubeListBuilder.create().texOffs(0,0).addBox(-4,-8,-4,8,8,8),PartPose.offset(0,8,0));r.addOrReplaceChild("body",CubeListBuilder.create().texOffs(16,16).addBox(-4,0,-2,8,12,4),PartPose.offset(0,8,0));r.addOrReplaceChild("left_arm",CubeListBuilder.create().texOffs(40,16).addBox(-1,0,-2,4,12,4),PartPose.offset(5,8,0));r.addOrReplaceChild("right_arm",CubeListBuilder.create().texOffs(40,16).mirror().addBox(-3,0,-2,4,12,4),PartPose.offset(-5,8,0));r.addOrReplaceChild("left_leg",CubeListBuilder.create().texOffs(0,16).addBox(-2,0,-2,4,12,4),PartPose.offset(2,20,0));r.addOrReplaceChild("right_leg",CubeListBuilder.create().texOffs(0,16).mirror().addBox(-2,0,-2,4,12,4),PartPose.offset(-2,20,0));return LayerDefinition.create(m,64,64);}@Override public void setupAnim(BountyHunterEntity e,float swing,float amount,float age,float yaw,float pitch){head.yRot=yaw*((float)Math.PI/180F);head.xRot=pitch*((float)Math.PI/180F);rightArm.xRot=Mth.cos(swing*.6662F+(float)Math.PI)*2*amount*.5F;leftArm.xRot=Mth.cos(swing*.6662F)*2*amount*.5F;rightLeg.xRot=Mth.cos(swing*.6662F)*1.4F*amount;leftLeg.xRot=Mth.cos(swing*.6662F+(float)Math.PI)*1.4F*amount;}@Override public void renderToBuffer(PoseStack ps,VertexConsumer vc,int light,int overlay,int color){head.render(ps,vc,light,overlay,color);body.render(ps,vc,light,overlay,color);leftArm.render(ps,vc,light,overlay,color);rightArm.render(ps,vc,light,overlay,color);leftLeg.render(ps,vc,light,overlay,color);rightLeg.render(ps,vc,light,overlay,color);}}
